from pathlib import Path
import sys

NEW_CURRENT = r'''function renderCurrent(){
 state.currentBudgetMode=state.currentBudgetMode||'current';
 view.innerHTML=`<div class="card budget-calendar-card"><div class="budget-calendar-head"><div><h2>Бюджет по месяцам</h2><div class="muted">Рабочий вид бюджета: значения до НДС, база неизменна, все подтверждённые изменения сохраняются автоматически.</div></div><div class="field budget-date-field"><label>Состояние на дату</label><input id="asOf" type="date"><div class="help">Пусто = актуальное состояние</div></div></div><div class="budget-toolbar"><div class="segmented" id="budgetMode"><button data-budget-mode="current" class="${state.currentBudgetMode==='current'?'active':''}">Актуально</button><button data-budget-mode="base" class="${state.currentBudgetMode==='base'?'active':''}">База</button><button data-budget-mode="delta" class="${state.currentBudgetMode==='delta'?'active':''}">Изменения</button></div><div class="budget-toolbar-right"><div class="field budget-search-field"><label>Поиск</label><input id="budgetSearch" placeholder="Бренд, продукт, канал..."></div><div class="budget-export-actions"><button id="exportCurrentBudget" class="btn">Выгрузить актуальный бюджет</button><button id="exportBudgetHistory" class="btn">Выгрузить историю</button></div></div></div><div id="budgetSummary"></div><div class="help budget-calendar-help">Нажмите на сумму в конечной строке канала, чтобы добавить или снять бюджет. Комментарий обязателен. Синяя точка означает, что у ячейки есть история изменений.</div><div id="budgetMatrix"></div></div>`;
 const date=document.getElementById('asOf'),search=document.getElementById('budgetSearch');
 date.onchange=renderBudgetMatrix;search.oninput=renderBudgetMatrix;
 document.querySelectorAll('[data-budget-mode]').forEach(b=>b.onclick=()=>{state.currentBudgetMode=b.dataset.budgetMode;document.querySelectorAll('[data-budget-mode]').forEach(x=>x.classList.toggle('active',x===b));renderBudgetMatrix();});
 document.getElementById('exportCurrentBudget').onclick=exportCurrentBudgetMatrix;
 document.getElementById('exportBudgetHistory').onclick=()=>E.exportHistory(state.project);
 renderBudgetMatrix();
}
function budgetCleanName(name){return String(name??'').replace(/\s+flowchart\b.*$/i,'').replace(/\s+флоучарт\b.*$/i,'').trim()||'—';}
function budgetMonthArray(n,key){if(Array.isArray(n?.[key]))return n[key].map(x=>Number(x||0));const out=Array(12).fill(0);for(const child of n?.children?.values?.()||[]){const a=budgetMonthArray(child,key);for(let i=0;i<12;i++)out[i]+=a[i];}return out;}
function budgetAdjustment(n,key){const v=Number(n?.[key]);if(Number.isFinite(v))return v;let sum=0;for(const child of n?.children?.values?.()||[])sum+=budgetAdjustment(child,key);return sum;}
function budgetNodeNumbers(n,mode){const baseMonths=budgetMonthArray(n,'baseMonths'),currentMonths=budgetMonthArray(n,'currentMonths'),baseAdj=budgetAdjustment(n,'baseAdjustment'),currentAdj=budgetAdjustment(n,'currentAdjustment');if(mode==='base')return {months:baseMonths,adjustment:baseAdj,total:Number(n.base??baseMonths.reduce((a,b)=>a+b,0)+baseAdj)};if(mode==='delta')return {months:currentMonths.map((v,i)=>v-baseMonths[i]),adjustment:currentAdj-baseAdj,total:Number(n.delta??((currentMonths.reduce((a,b)=>a+b,0)+currentAdj)-(baseMonths.reduce((a,b)=>a+b,0)+baseAdj)))};return {months:currentMonths,adjustment:currentAdj,total:Number(n.current??currentMonths.reduce((a,b)=>a+b,0)+currentAdj)};}
function budgetPlain(k){const n=Number(k||0),rub=n/100,hasKop=Math.abs(n%100)>0;return new Intl.NumberFormat('ru-RU',{minimumFractionDigits:hasKop?2:0,maximumFractionDigits:2}).format(rub);}
function budgetCell(v,mode){const n=Number(v||0);if(!n)return '<span class="budget-zero">—</span>';const cls=mode==='delta'?(n>0?'diff-pos':'diff-neg'):'';return `<span class="${cls}">${mode==='delta'&&n>0?'+':''}${budgetPlain(n)}</span>`;}
function budgetCollectRows(tree){const rows=[];const walk=(node,depth,path)=>{const raw=String(node?.name??'').trim(),placeholder=!raw||raw==='—'||raw==='-';const label=placeholder?'':budgetCleanName(raw),nextPath=placeholder?path:[...path,label];if(!placeholder)rows.push({node,depth,path:nextPath,label,leaf:!!node.leafId});for(const child of node?.children?.values?.()||[])walk(child,placeholder?depth:depth+1,nextPath);};for(const child of tree.children.values())walk(child,0,[]);return rows;}
function budgetDescendantLeafIds(node){const ids=[];const walk=n=>{if(n?.leafId)ids.push(n.leafId);for(const c of n?.children?.values?.()||[])walk(c);};walk(node);return new Set(ids);}
function budgetOperationHistory(node,monthKey){const ids=budgetDescendantLeafIds(node),status=C.buildState(state.project).status,items=[];for(const op of [...(state.project.operations||[])].sort(C.opSort)){if(op.type==='ANNUAL_ADJUSTMENT'){if(monthKey!=='adjustment'||!ids.has(op.payload?.leafId))continue;items.push({date:op.eventDate,number:op.number,type:typeLabel(op.type),delta:Number(op.payload?.delta||0),comment:op.comment,status:status.get(op.id)===false?'Отменено':'Действует'});continue;}for(const leg of op.payload?.legs||[]){if(!ids.has(leg.leafId)||Number(leg.month)!==Number(monthKey))continue;items.push({date:op.eventDate,number:op.number,type:typeLabel(op.type),delta:Number(leg.delta||0),comment:op.comment,status:status.get(op.id)===false?'Отменено':'Действует'});}}
 return items;
}
function budgetHistoryPopover(items){if(!items.length)return '';const rows=items.slice().reverse().slice(0,12).map(h=>`<div class="budget-history-item"><div><b>${esc(h.date)}</b><span class="budget-history-op">${esc(h.number||'')}</span></div><div class="${h.delta>=0?'diff-pos':'diff-neg'}">${h.delta>=0?'+':''}${budgetPlain(h.delta)} ₽</div><div>${esc(h.comment||'')}</div>${h.status==='Отменено'?'<div class="budget-history-cancelled">Отменено</div>':''}</div>`).join('');return `<div class="budget-history-popover"><div class="budget-history-title">История изменений</div>${rows}${items.length>12?`<div class="help">Ещё ${items.length-12} — в разделе «История изменений»</div>`:''}</div>`;}
function budgetDisplayCell(row,value,monthKey,mode,asOf){const history=budgetOperationHistory(row.node,monthKey),editable=row.leaf&&mode==='current'&&!asOf,hasHistory=history.length>0,content=budgetCell(value,mode);if(editable)return `<div class="budget-edit-cell ${hasHistory?'has-history':''}"><button type="button" class="budget-value-btn" data-budget-edit="${esc(row.node.leafId)}" data-budget-month="${esc(String(monthKey))}" title="Нажмите, чтобы изменить бюджет">${content}${hasHistory?'<span class="budget-history-dot" aria-label="Есть история"></span>':''}</button>${budgetHistoryPopover(history)}</div>`;if(hasHistory)return `<div class="budget-edit-cell has-history budget-readonly-history"><span>${content}<span class="budget-history-dot" aria-label="Есть история"></span></span>${budgetHistoryPopover(history)}</div>`;return content;}
function budgetToday(){const d=new Date(Date.now()-new Date().getTimezoneOffset()*60000);return d.toISOString().slice(0,10);}
async function commitBudgetCellMutation(mutator){const backup=JSON.parse(JSON.stringify(state.project));try{const result=mutator();markUnsaved();const saved=await persistProjectState({archive:true});state.unsaved=false;if(saved.archiveWarning)alert(saved.archiveWarning);refreshWorkspace(false).catch(()=>{});return result;}catch(e){state.project=backup;state.unsaved=false;renderChrome();throw e;}}
function openBudgetCellEditor(leafId,monthKey){const built=C.buildState(state.project),line=built.lines.get(leafId);if(!line)return alert('Бюджетная строка не найдена.');const isAdjustment=monthKey==='adjustment',month=isAdjustment?null:Number(monthKey),current=isAdjustment?Number(line.currentAdjustment||0):Number(line.current?.[month]||0),path=line.path.join(' → '),label=isAdjustment?'Корректировка вне месяцев':C.MONTHS[month];showModal(`<h3>Изменить бюджет</h3><div class="budget-edit-path">${esc(path)}</div><div class="budget-edit-context"><span>${esc(label)}</span><b>${budgetPlain(current)} ₽</b></div><div class="field"><label>Действие</label><div class="segmented budget-direction"><button type="button" data-budget-direction="ADD" class="active">+ Добавить</button><button type="button" data-budget-direction="REMOVE">− Снять</button></div></div><div class="row"><div class="field"><label>Сумма изменения, ₽</label><input id="budgetEditAmount" inputmode="decimal" placeholder="0"></div><div class="field"><label>Дата изменения</label><input id="budgetEditDate" type="date" value="${budgetToday()}"></div></div><div class="field"><label>Комментарий <span class="required-mark">обязательно</span></label><textarea id="budgetEditComment" placeholder="Например: дополнительный бюджет по согласованию клиента"></textarea><div class="help">Комментарий попадёт в историю и останется в актуальном контрольном файле.</div></div><div id="budgetEditPreview" class="budget-edit-preview"></div><div class="actions modal-actions"><button data-close class="btn">Отмена</button><button id="budgetEditConfirm" class="btn primary" disabled>Подтвердить изменение</button></div>`,close=>{let direction='ADD';const amount=document.getElementById('budgetEditAmount'),comment=document.getElementById('budgetEditComment'),date=document.getElementById('budgetEditDate'),confirmBtn=document.getElementById('budgetEditConfirm'),preview=document.getElementById('budgetEditPreview');const update=()=>{let kop=0;try{kop=C.rubToKopecks(amount.value||0);}catch(_e){kop=0;}const signed=direction==='ADD'?kop:-kop,next=current+signed,valid=kop>0&&comment.value.trim().length>0&&date.value&&next>=0;preview.innerHTML=kop>0?`<span>${budgetPlain(current)} ₽</span><b>${signed>=0?'+':'−'} ${budgetPlain(Math.abs(signed))} ₽</b><span>=</span><strong class="${next<0?'diff-neg':''}">${budgetPlain(next)} ₽</strong>`:'<span class="muted">Введите сумму — здесь будет показан результат изменения.</span>';confirmBtn.disabled=!valid;};document.querySelectorAll('[data-budget-direction]').forEach(b=>b.onclick=()=>{direction=b.dataset.budgetDirection;document.querySelectorAll('[data-budget-direction]').forEach(x=>x.classList.toggle('active',x===b));update();});amount.oninput=update;comment.oninput=update;date.onchange=update;confirmBtn.onclick=async()=>{try{confirmBtn.disabled=true;const kop=C.rubToKopecks(amount.value);if(isAdjustment){const delta=direction==='ADD'?Math.abs(kop):-Math.abs(kop);await commitBudgetCellMutation(()=>C.addAnnualAdjustmentOperation(state.project,{leafId,amountKopecks:delta,eventDate:date.value,comment:comment.value.trim()}));}else{await commitBudgetCellMutation(()=>C.addBudgetOperation(state.project,{leafId,month,amountKopecks:Math.abs(kop),eventDate:date.value,comment:comment.value.trim(),mode:direction}));}close();render();}catch(e){alert(e.message);update();}};update();});}
function budgetBindEditableCells(){document.querySelectorAll('[data-budget-edit]').forEach(b=>b.onclick=()=>openBudgetCellEditor(b.dataset.budgetEdit,b.dataset.budgetMonth));}
function budgetSafeFilePart(s){return String(s||'').trim().replace(/[\\/:*?"<>|]+/g,'_').replace(/\s+/g,'_');}
function exportCurrentBudgetMatrix(){if(!globalThis.XLSX)return alert('Библиотека Excel не загрузилась.');const asOf=document.getElementById('asOf')?.value||null,built=C.buildState(state.project,asOf),rows=[[...state.project.hierarchyLabels,...C.MONTHS,'Корректировка вне месяцев, ₽','Итого до НДС, ₽']];for(const line of [...built.lines.values()].sort((a,b)=>C.pathKey(a.path).localeCompare(C.pathKey(b.path)))){const total=line.current.reduce((a,b)=>a+b,0)+Number(line.currentAdjustment||0);rows.push([...line.path,...line.current.map(v=>v/100),Number(line.currentAdjustment||0)/100,total/100]);}const wb=XLSX.utils.book_new(),ws=XLSX.utils.aoa_to_sheet(rows);XLSX.utils.book_append_sheet(wb,ws,'Актуальный бюджет');const suffix=asOf||budgetToday();XLSX.writeFile(wb,`Актуальный_бюджет_${budgetSafeFilePart(state.project.projectName)}_${budgetSafeFilePart(state.project.period)}_${suffix}.xlsx`,{compression:true});}
function renderBudgetMatrix(){const asOf=document.getElementById('asOf')?.value||null,query=C.normalizeText(document.getElementById('budgetSearch')?.value||''),mode=state.currentBudgetMode||'current',tree=C.aggregateTree(state.project,asOf);const summary=document.getElementById('budgetSummary');if(summary)summary.innerHTML=`<div class="grid cols-3 budget-summary"><div><span class="muted">База до НДС</span><div class="metric">${money(tree.base)}</div></div><div><span class="muted">Изменения</span><div class="metric ${tree.delta>=0?'diff-pos':'diff-neg'}">${tree.delta>=0?'+':''}${money(tree.delta)}</div></div><div><span class="muted">Актуально до НДС</span><div class="metric">${money(tree.current)}</div></div></div>`;let rows=budgetCollectRows(tree);if(query)rows=rows.filter(r=>C.normalizeText(r.path.join(' → ')).includes(query));const body=rows.map(r=>{const x=budgetNodeNumbers(r.node,mode),level=state.project.hierarchyLabels?.[Number(r.node.level)]||'',depth=Math.min(r.depth,6);return `<tr class="budget-row ${r.leaf?'budget-leaf':'budget-group'} budget-depth-${Math.min(depth,3)}"><td class="budget-structure"><div style="padding-left:${depth*14}px"><span class="budget-row-name">${esc(r.label)}</span>${level?`<span class="budget-level">${esc(level)}</span>`:''}</div></td>${x.months.map((v,i)=>`<td class="money">${budgetDisplayCell(r,v,i,mode,asOf)}</td>`).join('')}<td class="money budget-adjustment">${budgetDisplayCell(r,x.adjustment,'adjustment',mode,asOf)}</td><td class="money budget-total">${budgetCell(x.total,mode)}</td></tr>`;}).join('');const matrix=document.getElementById('budgetMatrix');if(matrix){matrix.innerHTML=`<div class="budget-matrix-wrap"><table class="budget-matrix"><thead><tr><th class="budget-structure">Структура</th>${C.MONTHS.map(m=>`<th class="money">${esc(m.slice(0,3))}</th>`).join('')}<th class="money budget-adjustment">Корр. вне мес.</th><th class="money budget-total">Итого до НДС, ₽</th></tr></thead><tbody>${body||'<tr><td colspan="15" class="empty">По вашему фильтру строк нет.</td></tr>'}</tbody></table></div>`;budgetBindEditableCells();}}
'''

